head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > P > defaultValue]<br/>Key 에 값(Value)이 없으면 적용될 값을 설정합니다.",
    "validation" : [
        "Key 의 defaultValue 속성을 설정하지 않으면 DataMap 모듈의 defaultValue 속성이 적용됩니다.",
        "Key 에 값(Value)이 없을때 적용될 값을 설정합니다.",
        "''(Empty String)은 값이 있는 것으로 처리되며 Key 의 값(Value)이 null 이거나 정의하지 않은 경우 적용됩니다. 단, useNull=true 인 경우 Key 에 설정된 값(Value)이 null 이면 적용되지 않습니다.",
        "useNull=false 일때 Submission 모듈, setEmptyValue() 또는 setArray(), setJSON(), setXML() 메소드로 null 설정 시 defaultVaue 속성값이 적용됩니다. 단, 예외적으로 set() 메소드로 null 설정 시 ''(Empty String)이 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // 조건 설정       
    let properties = {
        defaultValue: con_defaultValue.getText(),     
        useNull: con_useNull.getText(),
    };    

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);      

    $c.gcm.createLabel('label="EmptyString 은 input 의 값을 삭제 후 getJSON 버튼을 클릭하여 확인"', '', 'label1');

    // target 생성    
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strInput = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataMap ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="map">';        
    strTarget += '<w2:keyInfo>';
    strTarget += '<w2:key dataType="text" id="key1" name="name1"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key2" name="name1"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key3" name="name1"></w2:key>';
    strTarget += '<w2:key dataType="text" id="key4" name="name1"></w2:key>';
    strTarget += '</w2:keyInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<key1><![CDATA[]]></key1>';
    strTarget += '<key2></key2>';
    strTarget += '<key4><![CDATA[dm_data4]]></key4>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataMap>';       

    $p.data.create(strTarget);

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    scwin.btn_getJSON_onclick();
}   



scwin.btn_getJSON_onclick = function (e) {
    let rtn = target1.getJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setEmptyValue_onclick = function (e) {
	target1.setEmptyValue();

    scwin.btn_getJSON_onclick();
};



scwin.btn_setJSON_onclick = function (e) {
	target1.setJSON({key1:null, key2:null, key3:null, key4:"dm_data4"});

    scwin.btn_getJSON_onclick();
};



scwin.btn_set_onclick = function (e) {
	target1.set("key1", null);
    target1.set("key2", null);
    target1.set("key3", null);
    target1.set("key4", "dm_data4");

    scwin.btn_getJSON_onclick();
};
